const path = require('path');
const globalModules = path.join(require('child_process').execSync('npm root -g').toString().trim());
const Database = require(path.join(globalModules, 'better-sqlite3'));
const db = new Database('/workspace/world.db');

// Check all users with tau2Retail skill
console.log('=== tau2Retail USERS ===');
const retailUsers = db.prepare(\"SELECT user_id, name, email, skill_ids_json FROM users WHERE skill_ids_json LIKE '%tau2Retail%'\").all();
retailUsers.forEach(u => console.log(JSON.stringify(u)));

// Check all tau2Retail orders
console.log('\n=== ALL tau2Retail ORDERS ===');
const orders = db.prepare(\"SELECT order_id, customer_id, status FROM orders WHERE source_skill='tau2Retail'\").all();
orders.forEach(o => console.log(JSON.stringify(o)));

// Search for ORD-D7E869 or similar format across all orders
console.log('\n=== SEARCH ORD-D7E869 ===');
const allOrders = db.prepare(\"SELECT order_id, customer_id, status FROM orders WHERE order_id LIKE '%D7E869%'\").all();
allOrders.forEach(o => console.log(JSON.stringify(o)));

// Check all orders for all Maya Chen users
console.log('\n=== ALL ORDERS FOR MAYA CHEN USERS ===');
['user_d3d5d0c8', 'user_4d870b51', 'user_fa209a3f'].forEach(uid => {
  const uOrders = db.prepare('SELECT order_id, status, source_skill FROM orders WHERE customer_id=?').all(uid);
  console.log(uid + ': ' + JSON.stringify(uOrders));
});

db.close();
"

